alter table lab_private.provider_files add column key_version integer not null default 1;
create function public.lab_file_context(attempt uuid) returns jsonb language sql stable security invoker set search_path='' as $$
select jsonb_build_object('asset',to_jsonb(s),'file',(select to_jsonb(f) from lab_private.provider_files f join lab_private.provider_secrets k on k.workspace_id=f.workspace_id and k.provider=f.provider where f.workspace_id=j.workspace_id and f.provider=j.provider and f.asset_id=s.id and f.sha256=s.sha256 and f.key_version=k.key_version and(f.expires_at is null or f.expires_at>now()+interval '2 minutes'))) from lab.attempts a join lab.jobs j on j.id=a.job_id join lab.runs r on r.id=j.run_id join lab.plan_inputs pi on pi.plan_id=r.plan_id and pi.revision_id=r.revision_id join lab.assets s on s.id=(pi.snapshot->>'prepared_asset_id')::uuid and s.workspace_id=j.workspace_id where a.id=attempt and s.kind='prepared' and s.status='verified' and s.server_hash and s.sha256=pi.snapshot->>'prepared_sha256' $$;
create function public.lab_file_set(attempt uuid,remote_id text,state text,expires_at timestamptz) returns boolean language plpgsql security invoker set search_path='' as $$ declare j lab.jobs;s lab.assets;version integer;begin
 select j0.* into j from lab.jobs j0 join lab.attempts a on a.job_id=j0.id where a.id=attempt;
 select a0.* into s from lab.assets a0 join lab.plan_inputs pi on (pi.snapshot->>'prepared_asset_id')::uuid=a0.id join lab.runs r on r.plan_id=pi.plan_id and r.revision_id=pi.revision_id where r.id=j.run_id and a0.workspace_id=j.workspace_id and a0.kind='prepared' and a0.status='verified' and a0.server_hash;
 if s.id is null or remote_id is null or length(remote_id)>500 or state not in('ready','processing') then raise exception 'REMOTE_FILE_INVALID';end if;
 if(j.provider='google' and remote_id!~'^https://generativelanguage.googleapis.com/v1beta/files/[A-Za-z0-9_-]+$') or(j.provider<>'google' and remote_id!~'^[A-Za-z0-9_-]+$') then raise exception 'REMOTE_FILE_ID_INVALID';end if;
 select key_version into version from lab_private.provider_secrets where workspace_id=j.workspace_id and provider=j.provider;
 insert into lab_private.provider_files(workspace_id,provider,asset_id,sha256,remote_id,state,expires_at,last_verified_at,key_version) values(j.workspace_id,j.provider,s.id,s.sha256,remote_id,state,expires_at,now(),version) on conflict(workspace_id,provider,asset_id) do update set sha256=excluded.sha256,remote_id=excluded.remote_id,state=excluded.state,expires_at=excluded.expires_at,last_verified_at=excluded.last_verified_at,key_version=excluded.key_version;return true;end $$;
create function public.lab_file_defer(attempt uuid,metadata jsonb,processing boolean) returns boolean language plpgsql security invoker set search_path='' as $$ declare j lab.jobs;q lab_private.quota_reservations;begin
 select j0.* into j from lab.jobs j0 join lab.attempts a on a.job_id=j0.id where a.id=attempt;perform 1 from lab_private.provider_runtime where provider=j.provider for update;
 select * into q from lab_private.quota_reservations where attempt_id=attempt for update;
 if q.status='held' then update lab_private.usage_budgets set reserved_usd=greatest(0,reserved_usd-q.reserved_usd) where workspace_id=j.workspace_id and provider=j.provider;update lab_private.quota_reservations set status='released' where id=q.id;end if;
 update lab.attempts t set completed_at=now(),milestone='file_prepared',metadata=t.metadata||lab_file_defer.metadata where id=attempt and completed_at is null;
 update lab.jobs set status='queued',lease_until=null,due_at=now()+case when processing then interval '1 minute' else interval '1 second' end where id=j.id;return true;end $$;
revoke execute on function public.lab_file_context(uuid),public.lab_file_set(uuid,text,text,timestamptz),public.lab_file_defer(uuid,jsonb,boolean) from public,anon,authenticated;
grant execute on function public.lab_file_context(uuid),public.lab_file_set(uuid,text,text,timestamptz),public.lab_file_defer(uuid,jsonb,boolean) to service_role;

create function public.lab_file_expired(attempt uuid) returns boolean language plpgsql security invoker set search_path='' as $$ begin update lab_private.provider_files f set state='expired',expires_at=now() where f.workspace_id=(select workspace_id from lab.attempts where id=attempt) and f.provider=(select j.provider from lab.jobs j join lab.attempts a on a.job_id=j.id where a.id=attempt) and f.asset_id=(select (pi.snapshot->>'prepared_asset_id')::uuid from lab.plan_inputs pi join lab.runs r on r.plan_id=pi.plan_id and r.revision_id=pi.revision_id join lab.jobs j on j.run_id=r.id join lab.attempts a on a.job_id=j.id where a.id=attempt);return true;end $$;
revoke execute on function public.lab_file_expired(uuid) from public,anon,authenticated;
grant execute on function public.lab_file_expired(uuid) to service_role;
